    border-right: var(--line) solid var(--black);
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 6vmin;
  }
  .composition {
    position: relative;
    width: 100%;
    aspect-ratio: 1 / 1;
    background: var(--white);
